<script setup>
import {computed,onMounted,ref,watch} from 'vue'
import {Search,ArrowUpRight} from 'lucide-vue-next'
import {api} from '../services/api'
import PlayerHeadshot from '../components/player/PlayerHeadshot.vue';import TeamLogo from '../components/team/TeamLogo.vue';import CustomSelect from '../components/ui/CustomSelect.vue';import LoadingState from '../components/ui/LoadingState.vue'
const players=ref([]),query=ref(''),position=ref('all'),team=ref('all'),limit=ref(48),loading=ref(true),error=ref('')
const load=async()=>{loading.value=true;error.value='';try{players.value=await api.players()}catch(caught){error.value=caught?.message||'The player directory could not be loaded.'}finally{loading.value=false}}
onMounted(load)
watch([query,position,team],()=>limit.value=48)
const teams=computed(()=>[...new Map(players.value.map(p=>[p.team_id,{id:p.team_id,name:p.team_name,abbr:p.team_abbr}])).values()].sort((a,b)=>a.name.localeCompare(b.name)))
const teamOptions=computed(()=>[{value:'all',label:'All 30 teams',meta:'MLB'},...teams.value.map(item=>({value:String(item.id),label:item.name,meta:item.abbr}))])
const filtered=computed(()=>players.value.filter(p=>(position.value==='all'||p.position_abbr===position.value)&&(team.value==='all'||String(p.team_id)===team.value)&&(!query.value||`${p.name} ${p.team_name} ${p.position}`.toLowerCase().includes(query.value.toLowerCase()))))
const visible=computed(()=>filtered.value.slice(0,limit.value))
const positions=[['all','All'],['P','Pitchers'],['C','Catchers'],['IF','Infield'],['OF','Outfield']]
const matchPosition=(p,wanted)=>wanted==='IF'?['1B','2B','3B','SS'].includes(p.position_abbr):wanted==='OF'?['LF','CF','RF','OF'].includes(p.position_abbr):p.position_abbr===wanted
const setPosition=value=>{position.value=value}
const positionFiltered=computed(()=>players.value.filter(p=>position.value==='all'||matchPosition(p,position.value)))
const finalFiltered=computed(()=>positionFiltered.value.filter(p=>(team.value==='all'||String(p.team_id)===team.value)&&(!query.value||`${p.name} ${p.team_name} ${p.position}`.toLowerCase().includes(query.value.toLowerCase()))))
const finalVisible=computed(()=>finalFiltered.value.slice(0,limit.value))
</script>
<style scoped>
@media(max-width:480px){.player-copy :deep(.team-logo){width:26px!important;height:26px!important}.player-copy :deep(.team-logo img){display:block}}
</style>
<template><div class="directory"><section class="directory-head"><span class="eyebrow">OFFICIAL MLB PLAYER INDEX</span><h1>The league,<br><i>face to face.</i></h1><p>Browse active MLB players by club or position, then open a profile for current-season production.</p></section><section class="player-tools"><label><Search :size="17"/><input v-model="query" placeholder="Search a player, team, or position"></label><CustomSelect v-model="team" :options="teamOptions" searchable placeholder="All 30 teams"/></section><div class="position-row"><button v-for="item in positions" :key="item[0]" :class="{active:position===item[0]}" @click="setPosition(item[0])">{{item[1]}}</button><span class="mono">{{finalFiltered.length}} PLAYERS</span></div><LoadingState v-if="loading" label="Building the player index" detail="Loading active rosters, positions and official player images."/><section v-else class="player-grid"><RouterLink v-for="player in finalVisible" :key="player.id" :to="`/players/${player.id}`" class="player-card"><div class="portrait"><PlayerHeadshot :id="player.id" :name="player.name" :size="180"/><span class="number mono">{{player.number?`#${player.number}`:'MLB'}}</span><ArrowUpRight class="open" :size="17"/></div><div class="player-copy"><div><h2>{{player.name}}</h2><span>{{player.position}} · {{player.bats||'—'}} / {{player.throws||'—'}}</span></div><TeamLogo :team="{id:player.team_id,name:player.team_name,abbr:player.team_abbr}" :size="30"/></div><footer><b>{{player.team_abbr}}</b><span>{{player.age}} YEARS OLD</span></footer></RouterLink></section><button v-if="limit<finalFiltered.length" class="more" @click="limit+=48">SHOW 48 MORE <span>{{finalFiltered.length-limit}} REMAINING</span></button><div v-if="!loading&&!finalFiltered.length" class="state">No players match those filters.</div></div></template>
<style scoped>.directory{display:grid;gap:20px}.directory-head{padding:35px 0 22px;border-bottom:1px solid var(--line)}h1{font-size:clamp(46px,7vw,92px);line-height:.88;letter-spacing:-.08em;margin:15px 0 25px}h1 i{font-style:normal;color:var(--orange)}p{max-width:590px;color:var(--muted);font-size:13px;line-height:1.7}.player-tools{display:flex;gap:9px}.player-tools label{height:44px;flex:1;display:flex;align-items:center;gap:9px;padding:0 14px;border:1px solid var(--line);background:var(--surface)}.player-tools input{width:100%;border:0;outline:0;background:transparent;font-size:11px}.player-tools :deep(.custom-select){min-width:250px}.position-row{display:flex;align-items:center;gap:5px;border-bottom:1px solid var(--line);padding-bottom:12px}.position-row button{border:0;background:transparent;padding:8px 12px;font:600 9px 'DM Mono';color:var(--muted);cursor:pointer}.position-row button.active{background:var(--ink);color:var(--paper)}.position-row span{margin-left:auto;font-size:9px;color:var(--muted)}.player-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:9px}.player-card{min-width:0;border:1px solid var(--line);background:var(--surface);text-decoration:none;overflow:hidden;transition:.2s}.player-card:hover{transform:translateY(-3px);border-color:var(--ink)}.portrait{height:190px;position:relative;display:flex;justify-content:center;align-items:flex-end;background:var(--wash);overflow:hidden}.portrait :deep(.headshot){width:100%!important;height:100%!important;border:0;border-radius:0}.number,.open{position:absolute;top:12px}.number{left:12px;font-size:8px;background:var(--ink);color:var(--paper);padding:5px 7px}.open{right:12px}.player-copy{display:flex;align-items:center;justify-content:space-between;gap:8px;padding:14px}.player-copy h2{font-size:14px;margin:0 0 4px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.player-copy>div{min-width:0}.player-copy span{font:500 8px 'DM Mono';color:var(--muted)}.player-card footer{display:flex;justify-content:space-between;padding:10px 14px;border-top:1px solid var(--line);font:600 8px 'DM Mono';color:var(--muted)}.player-card footer b{color:var(--text)}.more{justify-self:center;margin:15px 0;padding:13px 20px;border:1px solid var(--ink);background:var(--ink);color:var(--paper);font:600 9px 'DM Mono';cursor:pointer}.more span{color:var(--accent);margin-left:10px}.state{padding:70px;text-align:center;font:10px 'DM Mono';color:var(--muted)}@media(max-width:1100px){.player-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:780px){.player-grid{grid-template-columns:repeat(2,1fr)}.player-tools{flex-direction:column}.player-tools :deep(.custom-select){width:100%}.position-row{overflow-x:auto}.position-row button{flex:none}.position-row span{display:none}}@media(max-width:480px){.player-grid{grid-template-columns:1fr 1fr}.portrait{height:155px}.player-copy{padding:11px}.player-copy h2{font-size:12px}.player-copy :deep(img){display:none}.player-card footer span{display:none}}</style>
